import { DefaultError, useMutation } from '@tanstack/react-query';
import { useDataProvider, useNotify } from 'react-admin';
import { CrmDataProvider } from '../../providers/types';
import { Company } from '../../types';

type MutationArgs = {
    registrationNumber: string;
};

export function useGetCompanyDetails() {
    const notify = useNotify();
    const dataProvider = useDataProvider<CrmDataProvider>();
    return useMutation<Partial<Company>, DefaultError, MutationArgs>({
        mutationFn: async ({ registrationNumber }) => {
            return dataProvider.getCompanyDetails(registrationNumber);
        },
        onSuccess() {
            notify('Retrieved the company details from Bolagsverket', {
                type: 'success',
            });
        },
        onError() {
            notify('Failed to retrieve company details', {
                type: 'error',
            });
        },
    });
}
