import { createContext, ReactNode, useContext, useMemo } from 'react';
import { ContactGender, DealStage, NoteStatus } from '../types';
import {
    defaultCompanySectors,
    defaultContactGender,
    defaultDealCategories,
    defaultDealPipelineStatuses,
    defaultDealStages,
    defaultLogo,
    defaultNoteStatuses,
    defaultTaskTypes,
    defaultTitle,
} from './defaultConfiguration';

// Define types for the context value
export interface ConfigurationContextValue {
    companySectors: string[];
    dealCategories: string[];
    dealPipelineStatuses: string[];
    dealStages: DealStage[];
    noteStatuses: NoteStatus[];
    taskTypes: string[];
    title: string;
    logo: string;
    contactGender: ContactGender[];
    yearsFilterRange: number[];
}

export interface ConfigurationProviderProps
    extends Omit<ConfigurationContextValue, 'yearsFilterRange'> {
    startingYear: number;
    children: ReactNode;
}

// Create context with default value
export const ConfigurationContext = createContext<ConfigurationContextValue>({
    companySectors: defaultCompanySectors,
    dealCategories: defaultDealCategories,
    dealPipelineStatuses: defaultDealPipelineStatuses,
    dealStages: defaultDealStages,
    noteStatuses: defaultNoteStatuses,
    taskTypes: defaultTaskTypes,
    title: defaultTitle,
    logo: defaultLogo,
    contactGender: defaultContactGender,
    yearsFilterRange: [],
});

export const ConfigurationProvider = ({
    children,
    companySectors,
    dealCategories,
    dealPipelineStatuses,
    dealStages,
    logo,
    noteStatuses,
    taskTypes,
    title,
    contactGender,
    startingYear,
}: ConfigurationProviderProps) => {
    const yearsFilterRange = useMemo(() => {
        const currentYear = new Date().getFullYear();

        return Array.from(
            { length: currentYear - startingYear + 1 },
            (_, i) => startingYear + i
        ).toSorted((a, b) => b - a);
    }, [startingYear]);

    return (
        <ConfigurationContext.Provider
            value={{
                companySectors,
                dealCategories,
                dealPipelineStatuses,
                dealStages,
                logo,
                noteStatuses,
                title,
                taskTypes,
                contactGender,
                yearsFilterRange,
            }}
        >
            {children}
        </ConfigurationContext.Provider>
    );
};

export const useConfigurationContext = () => useContext(ConfigurationContext);
