import { CircularProgress } from '@mui/material';
import { MouseEventHandler, useCallback, useMemo } from 'react';
import { Button } from 'react-admin';
import { useFormContext, useWatch } from 'react-hook-form';
import { useGetCompanyDetails } from './hooks/useGetCompanyDetails';

export function CompanyGetDetailsButton() {
    const form = useFormContext();
    const { mutateAsync, isPending } = useGetCompanyDetails();

    const isRegistrationNumberValid = useMemo(() => {
        const fieldState = form.getFieldState('registration_number');
        return fieldState.isDirty && !fieldState.invalid;
    }, [form]);

    const registrationNumber = useWatch({ name: 'registration_number' });

    const handleClick: MouseEventHandler<HTMLButtonElement> =
        useCallback(async () => {
            if (!isRegistrationNumberValid) {
                return;
            }

            const company = await mutateAsync({
                registrationNumber,
            });

            for (const [key, value] of Object.entries(company)) {
                form.setValue(key, value);
            }
        }, [form, mutateAsync, isRegistrationNumberValid, registrationNumber]);

    return (
        <Button
            label="Get Company Details"
            onClick={handleClick}
            disabled={!isRegistrationNumberValid || isPending}
            startIcon={isPending ? <CircularProgress size={16} /> : null}
            size="medium"
        />
    );
}
