import { DefaultError, useMutation } from '@tanstack/react-query';
import { useDataProvider, useNotify } from 'react-admin';
import { CrmDataProvider } from '../../providers/types';
import { Contact } from '../../types';

type MutationArgs = {
    registrationNumber: string;
};

export function useGetContactDetails() {
    const notify = useNotify();
    const dataProvider = useDataProvider<CrmDataProvider>();
    return useMutation<Partial<Contact>, DefaultError, MutationArgs>({
        mutationFn: async ({ registrationNumber }) => {
            return dataProvider.getContactDetails(registrationNumber);
        },
        onSuccess() {
            notify('Retrieved the contact details from Bolagsverket', {
                type: 'success',
            });
        },
        onError() {
            notify('Failed to retrieve contact details', {
                type: 'error',
            });
        },
    });
}
